bool StructTraits<::ash::settings::google_drive::mojom::Status::DataView, ::ash::settings::google_drive::mojom::StatusPtr>::Read(
    ::ash::settings::google_drive::mojom::Status::DataView input,
    ::ash::settings::google_drive::mojom::StatusPtr* output) {
  bool success = true;
  ::ash::settings::google_drive::mojom::StatusPtr result(::ash::settings::google_drive::mojom::Status::New());
  
      if (success && !input.ReadRequiredSpace(&result->required_space))
        success = false;
      if (success && !input.ReadFreeSpace(&result->free_space))
        success = false;
      if (success && !input.ReadStage(&result->stage))
        success = false;
      if (success)
        result->listed_files = input.listed_files();
      if (success)
        result->is_error = input.is_error();
  *output = std::move(result);
  return success;
}

